def monotonic(l):
    """
    For list input:
    Return True if the list elements are monotonically increasing or decreasing and have no duplicates,
    along with the sum of the list elements as an integer.
    Return False if there are any duplicates.
    If the list is empty or has only one element, return True only.

    The function should not use any loops or in-built sorting methods.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    (True, 27)
    >>> monotonic([1, 1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    (True, -5)
    """
    # Handle empty or single element list: return True only
    if len(l) <= 1:
        return True

    # Check duplicates by comparing length with set length
    if len(l) != len(set(l)):
        return False

    # Define recursive helpers to check monotonic increasing or decreasing without loops

    def is_increasing(i=0):
        # Base case: reached last pair
        if i == len(l) - 1:
            return True
        # If current element is less than next, continue checking
        if l[i] < l[i + 1]:
            return is_increasing(i + 1)
        else:
            return False

    def is_decreasing(i=0):
        # Base case: reached last pair
        if i == len(l) - 1:
            return True
        # If current element is greater than next, continue checking
        if l[i] > l[i + 1]:
            return is_decreasing(i + 1)
        else:
            return False

    inc = is_increasing()
    dec = is_decreasing()

    if inc or dec:
        return True, sum(l)
    else:
        return False

