def parse_nested_parens(paren_string: str) -> List[int]:
    """ Input to this function is a string represnted multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    groups = paren_string.split()
    results = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
                if current_depth < 0:
                    raise ValueError("Malformed input: too many closing parentheses")
            else:
                # Invalid character encountered
                raise ValueError(f"Malformed input: invalid character '{ch}'")
        if current_depth != 0:
            raise ValueError("Malformed input: unbalanced parentheses")
        results.append(max_depth)
    return results

