    """
    Write a function which sotrts the given list of integers
    in ascedning order according to the sum of their digits.
    Note if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # The sign is ignored, but the first digit contributes negatively,
            # subsequent digits contribute positively.
            # For example: -12 => sum = -1 + 2 = 1
            return -int(s[1]) + sum(int(d) for d in s[2:])
        else:
            return sum(int(d) for d in s)

    # Sort by digit sum, stable sort preserves original order on ties
    return sorted(nums, key=digit_sum)

