def find_solution(a: int, b: int, n: int) -> tuple[int, int] | None:
    # Find integers x, y >= 0 with a*x + b*y = n
    # Return the pair with the smallest non-negative x or None if no solution.

    # Handle trivial cases
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        # Solve b*y = n, y >= 0
        if b != 0 and n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
        return None
    if b == 0:
        # Solve a*x = n, x >= 0
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return None

    # We'll try x from 0 upwards to find smallest x with non-negative y
    # because we want minimal non-negative x
    # For each x, y = (n - a*x)/b must be integer and >= 0
    # To avoid infinite loops, limit search by max x s.t. a*x <= n if a>0 else no upper bound
    # But since inputs can be any int, we must be careful

    # We try x starting from 0 upwards while a*x <= n if a > 0 or until no solution possible.
    # If a <= 0, just try some reasonable upper bound - but no constraints given.
    # We'll try up to max search limit = 10**6 to avoid infinite loops.

    MAX_ITER = 10**6

    # Define a function to check x and compute y
    def try_x(x: int) -> tuple[int, int] | None:
        diff = n - a * x
        if b == 0:
            return None
        if diff % b != 0:
            return None
        y = diff // b
        if y < 0:
            return None
        return (x, y)

    # If a > 0, limit x to max_x = n//a if n >= 0 else no solution if negative
    # If a < 0, x increases, but a*x decreases, so no upper bound.
    # We'll just try x from 0 up to MAX_ITER for safety.

    if a > 0:
        max_x = n // a if n >= 0 else -1
        if max_x < 0:
            return None
        limit = min(max_x, MAX_ITER)
    else:
        limit = MAX_ITER

    for x in range(limit + 1):
        sol = try_x(x)
        if sol is not None:
            return sol

    return None

def next_power_of_2(n: int) -> int:
    if n <= 1:
        # For n <= 1, smallest power of two >= n is 1
        return 1
    # If n is already a power of two, return n
    if (n & (n - 1)) == 0:
        return n
    # Otherwise, find the smallest power of two greater than n
    p = 1
    while p < n:
        p <<= 1
    return p

