def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[pos][val] = number of sequences of length pos starting with element val
    # We want sequences of length n, elements in 1..m,
    # with each next element at least twice the previous one
    # first element can be any from 1..m.

    # Base case: sequences of length 1, for each val in 1..m, count = 1
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for val in range(1, m + 1):
        dp[1][val] = 1

    for length in range(2, n + 1):
        for prev in range(1, m + 1):
            if dp[length - 1][prev] == 0:
                continue
            start = 2 * prev
            # next element must be >= 2 * prev
            for nxt in range(start, m + 1):
                dp[length][nxt] += dp[length - 1][prev]

    return sum(dp[n][1:])  # sum over all possible ending elements


