def get_total_number_of_sequences(m: int, n: int) -> int:
    """
    Count the number of length-n sequences of positive integers from 1 to m,
    that are nondecreasing and where each element from the second onward is at least twice the previous element.
    """
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(pos: int, prev: int) -> int:
        # pos: current position in the sequence (0-based)
        # prev: the value of the previous element in the sequence

        if pos == n:
            return 1

        total = 0
        # The next element must be >= prev (nondecreasing)
        # and >= 2 * prev if pos > 0
        start = prev if pos > 0 else 1
        # For pos > 0, also must be >= 2*prev, so take max of prev and 2*prev
        if pos > 0:
            start = max(start, 2 * prev)

        for val in range(start, m + 1):
            total += count_sequences(pos + 1, val)
        return total

    return count_sequences(0, 0)

