def find_solution(a: int, b: int, n: int) -> tuple[int, int] | None:
    """
    Find any one valid pair (x, y) of nonnegative integers that satisfies:
        a*x + b*y = n
    by trying nonnegative x values in increasing order starting from 0.
    Return the first such pair found or None if no solution exists.
    """
    if b == 0:
        # If b == 0, then a*x = n; check if n divisible by a and x >= 0
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return None

    if a == 0:
        # If a == 0, then b*y = n; check if n divisible by b and y >= 0
        if b != 0 and n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
        return None

    # General case: try x from 0 upwards until no more valid y possible
    x = 0
    while a * x <= n:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1

    return None

