def smallest_missing(arr: List[int]) -> int:
    # The array is sorted and contains non-negative integers starting from 0 or higher.
    # We want the smallest missing non-negative integer.
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        # If the value at mid is greater than mid, missing number is on left side
        if arr[mid] > mid:
            right = mid
        else:
            left = mid + 1
    return left

def permute_string(s: str) -> None:
    def backtrack(path, used):
        if len(path) == len(s):
            print("".join(path))
            return
        for i in range(len(s)):
            if used[i]:
                continue
            # Skip duplicates: if the current char is the same as previous and previous not used
            if i > 0 and s[i] == s[i-1] and not used[i-1]:
                continue
            used[i] = True
            path.append(s[i])
            backtrack(path, used)
            path.pop()
            used[i] = False

    s = sorted(s)
    backtrack([], [False] * len(s))

def highest_Power_of_2(n: int) -> int:
    # Assume n is a positive integer
    power = 1
    while power <= n:
        power <<= 1
    return power >> 1

