def even_Power_Sum(n: int) -> int:
    # Sum of fourth powers of first n even natural numbers starting from 2:
    # The even numbers are: 2, 4, 6, ..., 2n
    # Their fourth powers: (2k)^4 = 16 * k^4 for k=1 to n
    # So sum = 16 * sum(k^4 for k=1 to n)
    return 16 * sum(k**4 for k in range(1, n+1))

