def reverse_Array_Upto_K(arr: List[int], k: int) -> List[int]:
    # Reverse the first k elements (0 to k-1) of arr
    # If k is greater than length of arr, reverse entire arr
    if k > len(arr):
        k = len(arr)
    if k <= 0:
        return arr[:]
    return arr[:k][::-1] + arr[k:]

def recur_gcd(a: int, b: int) -> int:
    a, b = abs(a), abs(b)
    if b == 0:
        return a
    return recur_gcd(b, a % b)

