def capital_words_spaces(s: str) -> str:
    # Insert a space before every uppercase letter that is immediately preceded by a word character,
    # except at the start of the string.
    # This splits consecutive capitalized words but keeps sequences of uppercase letters together.
    return re.sub(r'(?<=\w)([A-Z])', r' \1', s)

