def lcm(a: int, b: int) -> int:
    # Since inputs are strictly positive integers, no zero or negative handling is needed.
    # Use gcd to compute lcm.
    def gcd(x: int, y: int) -> int:
        while y:
            x, y = y, x % y
        return x
    return a // gcd(a, b) * b

