def substract_elements(t):
    """
    Subtract all elements in the given nested tuple structure.

    Since the order and handling of varying lengths or depths are unspecified,
    this implementation:
    - Traverses the nested tuples in a depth-first, left-to-right order.
    - Subtracts elements in the order encountered: first element minus second minus third ...
    - Treats all integers found in nested tuples as operands.
    - If no integers found, returns 0.
    """
    def flatten(nested):
        for el in nested:
            if isinstance(el, tuple):
                yield from flatten(el)
            else:
                yield el

    elements = list(flatten(t))
    if not elements:
        return 0
    result = elements[0]
    for e in elements[1:]:
        result -= e
    return result

def get_noOfways(n: int) -> int:
    # Number of ways to tile a 2 x n board with 2 x 1 dominoes
    # Base cases
    if n == 0:
        return 1  # empty board - 1 way (do nothing)
    if n == 1:
        return 1  # only vertical dominoes

    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1

    for i in range(2, n + 1):
        dp[i] = dp[i-1] + dp[i-2]

    return dp[n]
